-- BAYUCOIN: S/20 en productos por moneda; valor interno S/0.20.
alter table public.loyalty_settings add column if not exists coin_value numeric(10,2) not null default 0.20 check (coin_value > 0);
update public.loyalty_settings set soles_per_point = 20.00, coin_value = 0.20, enabled = true where id = 1;
update public.loyalty_rewards set active = false where lower(title) = 'top cliente' and lower(description) like '%mejor cliente de la semana%';
create or replace function public.award_loyalty_points() returns trigger language plpgsql security definer set search_path to 'pg_catalog', 'public' as $function$ declare c public.customers%rowtype; s public.loyalty_settings%rowtype; pts integer; inserted_count integer := 0; begin if new.status = 'entregado' and old.status is distinct from 'entregado' and nullif(trim(coalesce(new.phone, '')), '') is not null then insert into public.customers(phone, full_name, last_order_at, lifetime_spend, marketing_consent) values(new.phone, new.customer_name, new.delivered_at, new.total, new.marketing_consent) on conflict(phone) do update set full_name = excluded.full_name, last_order_at = excluded.last_order_at, lifetime_spend = public.customers.lifetime_spend + excluded.lifetime_spend, marketing_consent = (public.customers.marketing_consent or excluded.marketing_consent), updated_at = now() returning * into c; select * into s from public.loyalty_settings where id = 1; if coalesce(s.enabled, true) then pts := floor(new.subtotal / coalesce(s.soles_per_point, 20))::integer; if pts > 0 then insert into public.loyalty_transactions(customer_id, order_id, points, kind, note) values(c.id, new.id, pts, 'earned', 'BAYUCOIN por pedido ' || new.number) on conflict(order_id, kind) do nothing; get diagnostics inserted_count = row_count; if inserted_count > 0 then update public.customers set points_balance = points_balance + pts where id = c.id; end if; end if; end if; end if; return new; end $function$;